// Env's DB/R2 bindings are generated by `wrangler types`. Secrets are installed
// separately with `wrangler secret put`, never embedded in wrangler.jsonc.
import { handleSync } from "./sync";
import { sourceLanguage, languageCodes } from "./language";
export { LibraryNotifications } from "./notifications";

export type StorageEnv = Env & { STORAGE_USERNAME?: string; STORAGE_PASSWORD?: string; NOTIFICATIONS_DISABLED?: string };
export type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export type ObjectValue = { [key: string]: Json };
type BlobRef = { sha256: string; size: number };
type DocumentRow = { id: string; revision: string; manifest_key: string; info_json: string; created: number; updated: number };
type TrashRow = { token: string; id: string; manifest_key: string; info_json: string; created: number; placement_json: string };
const MAX_JSON = 8 * 1024 * 1024;
const MAX_BLOB = 100 * 1024 * 1024;
const HASH = /^[0-9a-f]{64}$/;
const COMMIT = /^[0-9a-f-]{36}$/;

export class Failure extends Error {
  constructor(readonly status: number, message: string) { super(message); }
}

export function object(value: Json | undefined): ObjectValue {
  if (value === null || typeof value !== "object" || Array.isArray(value)) throw new Failure(400, "Expected an object");
  return value;
}

export function identity(value: string): string {
  if (!value || value.startsWith(".") || /[\\/:\x00-\x1f]/.test(value) || value.length > 200) throw new Failure(400, "Invalid document ID");
  return value;
}

export function revision(value: Json | undefined): string | null {
  if (value === null) return null;
  if (typeof value !== "string" || !COMMIT.test(value)) throw new Failure(400, "Invalid revision");
  return value;
}

export function reply(value: unknown, status = 200): Response {
  return Response.json(value, { status, headers: { "Cache-Control": "no-store" } });
}

export async function jsonBody(request: Request): Promise<ObjectValue> {
  if (!request.body) throw new Failure(400, "Missing body");
  const reader = request.body.getReader();
  const chunks: Uint8Array[] = [];
  let size = 0;
  for (;;) {
    const part = await reader.read();
    if (part.done) break;
    size += part.value.byteLength;
    if (size > MAX_JSON) { await reader.cancel(); throw new Failure(413, "Document manifest is too large"); }
    chunks.push(part.value);
  }
  const bytes = new Uint8Array(size);
  let offset = 0;
  for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
  try { return object(JSON.parse(new TextDecoder().decode(bytes))); }
  catch (error) { if (error instanceof Failure) throw error; throw new Failure(400, "Invalid JSON"); }
}

async function authorized(request: Request, username: string, password: string): Promise<boolean> {
  const value = request.headers.get("Authorization") || "";
  const encoder = new TextEncoder();
  const credentials = encoder.encode(`${username}:${password}`);
  const expected = "Basic " + btoa(Array.from(credentials, byte => String.fromCharCode(byte)).join(""));
  const [a, b] = await Promise.all([value, expected].map(v => crypto.subtle.digest("SHA-256", encoder.encode(v))));
  return crypto.subtle.timingSafeEqual(a, b);
}

function blobRef(value: Json | undefined, refs: Map<string, BlobRef>): void {
  const ref = object(value);
  if (typeof ref.sha256 !== "string" || !HASH.test(ref.sha256) || typeof ref.size !== "number" ||
      !Number.isSafeInteger(ref.size) || ref.size < 0 || ref.size > MAX_BLOB) throw new Failure(400, "Invalid blob reference");
  const previous = refs.get(ref.sha256);
  if (previous && previous.size !== ref.size) throw new Failure(400, "Conflicting blob sizes");
  refs.set(ref.sha256, { sha256: ref.sha256, size: ref.size });
}

function blobMap(value: Json | undefined, refs: Map<string, BlobRef>): void {
  for (const ref of Object.values(object(value))) blobRef(ref, refs);
}

export function validateDocument(doc: ObjectValue, id: string, refs: Map<string, BlobRef>, depth = 0): void {
  if (depth > 8 || doc.id !== id || doc.format !== "textfold/document-v1") throw new Failure(400, "Invalid document manifest");
  if (doc.meta !== null) {
    const meta = object(doc.meta);
    if (meta.id !== undefined && meta.id !== id) throw new Failure(400, "Metadata ID mismatch");
  }
  if (doc.notes !== null) object(doc.notes);
  const source = object(doc.source);
  for (const field of ["html", "markdown", "xml", "wiki_html", "reference"]) {
    if (source[field] !== null && typeof source[field] !== "string") throw new Failure(400, "Invalid document source");
  }
  if (source.pdf !== null) blobRef(source.pdf, refs);
  blobMap(source.originals, refs);
  blobMap(doc.images, refs);
  blobMap(object(doc.processing).replies, refs);
  blobMap(doc.extensions, refs);
  blobMap(doc.legacy, refs);
  for (const layer of Object.values(object(doc.layers))) object(layer);
  if (doc.previous !== null) validateDocument(object(doc.previous), id, refs, depth + 1);
  if (refs.size > 10000) throw new Failure(413, "Too many document blobs");
}

export function documentInfo(doc: ObjectValue, commit: string, created: number, updated: number): ObjectValue {
  const layers = object(doc.layers);
  const languages = Object.keys(layers).filter(k => k.startsWith("tr-")).map(k => k.slice(3)).sort();
  if (layers.en !== undefined) {
    const code = object(layers.en).lang;
    const base = typeof code === "string" && languageCodes.has(code) ? code
      : sourceLanguage(typeof object(doc.source).html === "string" ? object(doc.source).html as string : "");
    const existing = languages.indexOf(base);
    if (existing >= 0) languages.splice(existing, 1);
    languages.unshift(base);
  }
  const titles: ObjectValue = {};
  for (const [key, layer] of Object.entries(layers)) {
    if (key.startsWith("tr-") && typeof object(layer).title === "string") titles[key.slice(3)] = object(layer).title;
  }
  const notes = doc.notes === null ? {} : object(doc.notes);
  const info = { id: doc.id, meta: doc.meta, titles, languages,
    note_count: Array.isArray(notes.notes) ? notes.notes.length : 0,
    created, updated, revision: commit, readable: doc.meta !== null && object(doc.source).html !== null };
  if (new TextEncoder().encode(JSON.stringify(info)).byteLength > 256 * 1024) throw new Failure(413, "Document index is too large");
  return info;
}

export async function snapshot(env: StorageEnv, key: string, value: ObjectValue): Promise<void> {
  const text = JSON.stringify(value);
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  const checksum = Array.from(new Uint8Array(digest), b => b.toString(16).padStart(2, "0")).join("");
  const result = await env.BLOBS.put(key, text, { onlyIf: { etagDoesNotMatch: "*" },
    sha256: checksum, httpMetadata: { contentType: "application/json" }, customMetadata: { checksum } });
  if (!result && (await env.BLOBS.head(key))?.customMetadata?.checksum !== checksum) throw new Failure(409, "Commit ID already used");
}

export async function loadSnapshot(env: StorageEnv, key: string): Promise<ObjectValue> {
  const stored = await env.BLOBS.get(key);
  if (!stored || stored.size > MAX_JSON) throw new Failure(503, "Document snapshot unavailable");
  return object(await stored.json<Json>());
}

async function handle(request: Request, env: StorageEnv, ctx: ExecutionContext): Promise<Response> {
  if (!env.STORAGE_USERNAME || !env.STORAGE_PASSWORD) throw new Failure(503, "Storage authentication is not configured");
  if (!await authorized(request, env.STORAGE_USERNAME, env.STORAGE_PASSWORD)) throw new Failure(401, "Unauthorized");
  const url = new URL(request.url);
  const path = url.pathname;
  const method = request.method;
  const db = env.DB.withSession("first-primary");

  if (path.startsWith("/v2/")) return handleSync(request, env, ctx);
  if (method !== "GET" && method !== "HEAD" && !path.startsWith("/v1/blobs/")) {
    const upgraded = await db.prepare("SELECT sync_enabled FROM storage_identity WHERE singleton=1").first<{ sync_enabled: number }>();
    if (upgraded?.sync_enabled) throw new Failure(409, "Library uses record synchronization; update this client before writing");
  }

  if (path === "/v1/health" && method === "GET") return reply({ format: "textfold/storage-v1" });
  const blob = path.match(/^\/v1\/blobs\/([0-9a-f]{64})$/);
  if (blob) {
    const key = `blobs/${blob[1]}`;
    if (method === "HEAD") {
      const registered = await db.prepare("SELECT size FROM blobs WHERE hash = ?1").bind(blob[1]).first<{ size: number }>();
      return new Response(null, { status: registered && await env.BLOBS.head(key) ? 200 : 404 });
    }
    if (method === "GET") {
      const value = await env.BLOBS.get(key);
      if (!value) throw new Failure(404, "Blob not found");
      return new Response(value.body, { headers: { "Content-Type": "application/octet-stream", "Content-Length": String(value.size), "Cache-Control": "no-store" } });
    }
    if (method === "PUT") {
      const header = request.headers.get("Content-Length");
      const length = Number(header);
      if (header === null || !Number.isSafeInteger(length) || length < 0 || length > MAX_BLOB) throw new Failure(413, "Invalid blob size");
      // R2 verifies the streamed checksum before publishing an immutable blob.
      const value = await env.BLOBS.put(key, request.body || new Uint8Array(0), { sha256: blob[1], onlyIf: { etagDoesNotMatch: "*" } });
      const stored = value || await env.BLOBS.head(key);
      if (!stored || stored.size !== length) throw new Failure(400, "Blob checksum or size mismatch");
      await db.prepare("INSERT INTO blobs(hash, size) VALUES (?1, ?2) ON CONFLICT(hash) DO NOTHING").bind(blob[1], length).run();
      return reply({ sha256: blob[1], size: length });
    }
  }

  if (path === "/v1/documents" && method === "GET") {
    const after = url.searchParams.get("after") || "";
    const rows = await db.prepare("SELECT id, info_json FROM documents WHERE id > ?1 AND json_type(info_json, '$.meta') != 'null' ORDER BY id LIMIT 100").bind(after).all<{ id: string; info_json: string }>();
    return reply({ documents: rows.results.map(row => JSON.parse(row.info_json)), next: rows.results.length === 100 ? rows.results[99].id : null });
  }

  if (path === "/v1/trash/purge" && method === "POST") {
    const body = await jsonBody(request);
    if (typeof body.before !== "number" || !Number.isFinite(body.before)) throw new Failure(400, "Invalid cutoff");
    const removed = await db.prepare("DELETE FROM trash WHERE deleted_at < ?1 RETURNING token").bind(body.before).all<{ token: string }>();
    return reply({ removed: removed.results.map(row => row.token) });
  }

  if (path === "/v1/library") {
    const current = await db.prepare("SELECT revision, manifest_key FROM library_state WHERE singleton = 1").first<{ revision: string; manifest_key: string }>();
    if (method === "GET") return reply(current ? { ...await loadSnapshot(env, current.manifest_key), revision: current.revision } : { catalog: {}, zotero: {}, revision: null });
    if (method === "PUT") {
      const body = await jsonBody(request);
      const expected = revision(body.revision), commit = revision(body.commit);
      if (!commit) throw new Failure(400, "Missing commit ID");
      const state = { catalog: object(body.catalog), zotero: object(body.zotero) };
      if (current?.revision === commit) return reply({ revision: commit });
      const key = `library/${commit}.json`;
      await snapshot(env, key, state);
      const saved = expected === null
        ? await db.prepare("INSERT INTO library_state(singleton, revision, manifest_key) VALUES (1, ?1, ?2) ON CONFLICT(singleton) DO NOTHING").bind(commit, key).run()
        : await db.prepare("UPDATE library_state SET revision = ?1, manifest_key = ?2 WHERE singleton = 1 AND revision = ?3").bind(commit, key, expected).run();
      if (saved.meta.changes !== 1) throw new Failure(409, "Library state changed");
      return reply({ revision: commit });
    }
  }

  const match = path.match(/^\/v1\/documents\/([^/]+)(?:\/(info|trash|restore))?$/);
  if (!match) throw new Failure(404, "Not found");
  const id = identity(decodeURIComponent(match[1])), action = match[2];
  if (action === "restore" && method === "POST") {
    const candidate = await db.prepare("SELECT * FROM trash WHERE id = ?1 ORDER BY deleted_at DESC, token DESC LIMIT 1").bind(id).first<TrashRow>();
    if (!candidate) return reply({ placement: null });
    const commit = crypto.randomUUID(), now = Date.now() / 1000;
    const result = await db.batch([
      db.prepare("INSERT INTO documents(id, revision, manifest_key, info_json, created, updated) SELECT id, ?1, manifest_key, json_set(info_json, '$.revision', ?1, '$.updated', ?2), created, ?2 FROM trash WHERE token = ?3 ON CONFLICT(id) DO NOTHING").bind(commit, now, candidate.token),
      db.prepare("DELETE FROM trash WHERE token = ?1 AND EXISTS (SELECT 1 FROM documents WHERE id = ?2 AND revision = ?3)").bind(candidate.token, id, commit),
    ]);
    return reply({ placement: result[0].meta.changes === 1 ? JSON.parse(candidate.placement_json) : null });
  }
  if (action === "trash" && method === "POST") {
    const body = await jsonBody(request), token = revision(body.commit);
    if (!token) throw new Failure(400, "Missing trash token");
    const placement = body.placement === null ? {} : object(body.placement);
    const existing = await db.prepare("SELECT id FROM trash WHERE token = ?1").bind(token).first<{ id: string }>();
    if (existing) {
      if (existing.id !== id) throw new Failure(409, "Trash token already used");
      return reply({ token });
    }
    const result = await db.batch([
      db.prepare("INSERT INTO trash(token, id, manifest_key, info_json, created, deleted_at, placement_json) SELECT ?1, id, manifest_key, info_json, created, ?2, ?3 FROM documents WHERE id = ?4 ON CONFLICT(token) DO NOTHING").bind(token, Date.now() / 1000, JSON.stringify(placement), id),
      db.prepare("DELETE FROM documents WHERE id = ?1 AND EXISTS (SELECT 1 FROM trash WHERE token = ?2 AND trash.id = documents.id AND json_extract(trash.info_json, '$.revision') = documents.revision)").bind(id, token),
    ]);
    if (result[0].meta.changes !== 1) {
      const saved = await db.prepare("SELECT id FROM trash WHERE token = ?1").bind(token).first<{ id: string }>();
      if (saved?.id !== id) throw new Failure(404, "Document not found");
    }
    return reply({ token });
  }

  const current = await db.prepare("SELECT * FROM documents WHERE id = ?1").bind(id).first<DocumentRow>();
  if (method === "GET") {
    if (!current) throw new Failure(404, "Document not found");
    const info = object(JSON.parse(current.info_json));
    if (action === "info") {
      if (info.meta === null) throw new Failure(404, "Document is not indexed yet");
      return reply(info);
    }
    if (action) throw new Failure(405, "Method not allowed");
    return reply({ document: await loadSnapshot(env, current.manifest_key), info });
  }
  if (action) throw new Failure(405, "Method not allowed");
  if (method === "DELETE") {
    const result = await db.prepare("DELETE FROM documents WHERE id = ?1").bind(id).run();
    if (result.meta.changes !== 1) throw new Failure(404, "Document not found");
    return reply({ deleted: id });
  }
  if (method === "PUT") {
    const body = await jsonBody(request), doc = object(body.document);
    const expected = revision(body.revision), commit = revision(body.commit);
    if (!commit) throw new Failure(400, "Missing commit ID");
    if (current?.revision === commit) return reply(JSON.parse(current.info_json));
    const refs = new Map<string, BlobRef>();
    validateDocument(doc, id, refs);
    const registered = await db.prepare("SELECT COUNT(*) AS total FROM json_each(?1) AS ref JOIN blobs ON blobs.hash = json_extract(ref.value, '$.sha256') AND blobs.size = json_extract(ref.value, '$.size')").bind(JSON.stringify([...refs.values()])).first<{ total: number }>();
    if (registered?.total !== refs.size) throw new Failure(409, "Document references missing blobs");
    const now = Date.now() / 1000;
    const created = current?.created ?? (typeof doc.created === "number" && doc.created > 0 ? doc.created : now);
    const info = documentInfo(doc, commit, created, now), key = `manifests/${commit}.json`;
    await snapshot(env, key, doc);
    const saved = expected === null
      ? await db.prepare("INSERT INTO documents(id, revision, manifest_key, info_json, created, updated) VALUES (?1, ?2, ?3, ?4, ?5, ?6) ON CONFLICT(id) DO NOTHING").bind(id, commit, key, JSON.stringify(info), created, now).run()
      : await db.prepare("UPDATE documents SET revision = ?1, manifest_key = ?2, info_json = ?3, updated = ?4 WHERE id = ?5 AND revision = ?6").bind(commit, key, JSON.stringify(info), now, id, expected).run();
    if (saved.meta.changes !== 1) throw new Failure(409, "Document changed");
    return reply(info);
  }
  throw new Failure(405, "Method not allowed");
}

export default {
  async fetch(request, env, ctx): Promise<Response> {
    try { return await handle(request, env, ctx); }
    catch (error) {
      if (error instanceof Failure) return reply({ error: error.message }, error.status);
      if (error instanceof Error && error.message.includes("textfold_v2_write_required")) return reply({ error: "Update the client to use record synchronization" }, 409);
      console.error(JSON.stringify({ event: "storage_failure", type: error instanceof Error ? error.name : "Unknown" }));
      return reply({ error: "Storage operation failed" }, 503);
    }
  },
} satisfies ExportedHandler<StorageEnv>;
